const KEY='studyTracker.v30',CLOUD_ACCOUNT_KEY='studyTracker.cloudAccount',APPEARANCE_KEY='studyTracker.appearance.v1',NOTICE_KEY='studyTracker.notice',LAST_VIEW_PREFIX='studyTracker.lastView.v1';
