function datePlus(days){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function penSubject(){const total=PEN_MODULES.reduce((n,x)=>n+x[1].split('|').length,0);let i=0;return {id:'pen200',name:'PEN-200 (2023)',description:'Penetration Testing with Kali Linux — 90-day book plan',color:'#7c5cff',icon:'P2',modules:PEN_MODULES.map(([name,list])=>({id:uid(),name,topics:list.split('|').map(name=>({id:uid(),name,status:'not-started',due:datePlus(Math.min(89,Math.floor(i++*90/total))) }))}))}}
function sampleSubject(){const modules=[['1. Getting Started',['Define your learning goal','Set a target completion date','Choose study resources','Plan weekly study time','Create your first milestone']],['2. Core Concepts',['Read the introduction','Learn key terminology','Review the first concept','Summarize important ideas','Complete a short knowledge check']],['3. Guided Practice',['Follow a worked example','Repeat the example independently','Record useful notes','Identify difficult areas','Complete the practice exercise']],['4. Applied Learning',['Plan a small project','Complete project step one','Complete project step two','Review your results','Document what you learned']],['5. Review & Completion',['Revise important concepts','Retry incomplete exercises','Complete the final assessment','Write a learning summary','Mark the subject complete']]];let day=0;return {id:'sample-subject',name:'Sample Learning Course',description:'Example subject showing how modules, topics, deadlines and progress work. Edit or delete it when you are ready.',color:'#7c5cff',icon:'EX',modules:modules.map(([name,topics])=>({id:uid(),name,topics:topics.map(name=>({id:uid(),name,status:'not-started',due:datePlus(day++)}))}))}}
const seed={profile:null,settings:{theme:'nestlyra',sounds:true,notifications:true,fontStyle:'modern',textScale:'normal',loginImage:'',loginImagePosition:'center',loginImageShade:'balanced'},subjects:[sampleSubject()],tasks:[],events:[],jobApplications:[],notes:[{id:uid(),title:'How to use this sample',subjectId:'sample-subject',content:'Open the sample subject, update topic statuses, change due dates, add your own modules, or delete the sample and create a real subject.',updated:today()}],activity:[],activeWorkspace:'primary',workspaces:[{id:'primary',name:'My First Workspace',archived:false}]};
const cloudConfig=window.STUDY_TRACKER_CONFIG||{},sb=cloudConfig.supabaseUrl&&window.supabase?window.supabase.createClient(cloudConfig.supabaseUrl,cloudConfig.supabaseAnonKey):null;
let cloudUser=null,syncTimer=null,invalidatingSession=false,state=load(),viewName='dashboard',selectedSubject=state.subjects[0]?.id||'',selectedNote=state.notes[0]?.id,calDate=new Date(),timerSeconds=25*60,timerInitial=25*60,timerHandle=null,jobQuery='',jobFilter='All',jobSort='newest';
function normalizeState(x){const next=Object.assign(structuredClone(seed),x||{});next.settings={...seed.settings,...(x?.settings||{})};next.jobApplications=Array.isArray(next.jobApplications)?next.jobApplications:[];return next}
function load(){try{return normalizeState(JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{return structuredClone(seed)}}
function save(){if(state?.workspaces?.length&&typeof storeWorkspace==='function')storeWorkspace();localStorage.setItem(KEY,JSON.stringify(state));applyTheme();if(cloudUser&&sb){clearTimeout(syncTimer);syncTimer=setTimeout(syncCloud,450)}}
async function syncCloud(){if(!cloudUser||!sb)return;const payload=structuredClone(state);if(payload.profile)delete payload.profile.pin;const {error}=await sb.from('user_tracker_data').upsert({user_id:cloudUser.id,data:payload},{onConflict:'user_id'});if(error){console.error('Cloud sync failed',error.message);const check=await sb.auth.getUser();if(check.error||!check.data?.user)invalidateCloudSession('This account no longer exists. Create a new account to continue.')}else if(typeof groupPublishProgress==='function')groupPublishProgress()}
async function loadCloud(){const {data,error}=await sb.from('user_tracker_data').select('data').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;if(data?.data){state=normalizeState(data.data);state.profile=state.profile||{name:cloudUser.user_metadata?.full_name||cloudUser.email.split('@')[0]}}else{state=structuredClone(seed);state.profile={name:cloudUser.user_metadata?.full_name||cloudUser.email.split('@')[0],email:cloudUser.email};await syncCloud()}selectedSubject=state.subjects[0]?.id||'';selectedNote=state.notes[0]?.id;localStorage.setItem(KEY,JSON.stringify(state))}
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function pct(subject){const t=subject.modules.flatMap(m=>m.topics);return t.length?Math.round(t.filter(x=>x.status==='completed').length/t.length*100):0}
function allTopics(){return state.subjects.flatMap(s=>s.modules.flatMap(m=>m.topics.map(t=>({...t,subjectId:s.id,subject:s.name,module:m.name}))))}
function overall(){const t=allTopics();return t.length?Math.round(t.filter(x=>x.status==='completed').length/t.length*100):0}
function streak(){const days=new Set(state.activity.filter(a=>a.minutes>0).map(a=>a.date));let n=0,d=new Date();while(days.has(d.toISOString().slice(0,10))){n++;d.setDate(d.getDate()-1)}return n}
function subjectName(id){return state.subjects.find(s=>s.id===id)?.name||'General'}
function toast(msg){const x=document.querySelector('#toast');x.textContent=msg;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function markCloudAccount(user=cloudUser){if(user?.id)localStorage.setItem(CLOUD_ACCOUNT_KEY,user.id)}
function viewStorageKey(){const identity=cloudUser?.id||state.profile?.email||state.profile?.name||'local';return `${LAST_VIEW_PREFIX}:${String(identity).toLowerCase()}`}
function rememberView(name=viewName){if(!/^[a-z][a-z0-9-]*$/i.test(String(name||'')))return;try{localStorage.setItem(viewStorageKey(),name)}catch{}}
function restoreView(){let saved='';try{saved=localStorage.getItem(viewStorageKey())||''}catch{};viewName=/^[a-z][a-z0-9-]*$/i.test(saved)?saved:'dashboard'}
function updateViewHistory(name,{replace=false}={}){const next={...(history.state||{}),nestlyraView:name};try{history[replace?'replaceState':'pushState'](next,'',location.href)}catch{}}
function setNavigationOpen(open){const sidebar=document.querySelector('.sidebar'),expanded=Boolean(open);sidebar?.classList.toggle('open',expanded);app?.classList.toggle('nav-open',expanded);menuBtn?.setAttribute('aria-expanded',String(expanded))}
function clearClientAccount(){familyStopVoice?.();sessionStorage.removeItem('studyTracker.family.role');sessionStorage.removeItem('studyTracker.family.sessionType');sessionStorage.removeItem('studyTracker.family.loginIntent');sessionStorage.removeItem('studyTracker.forceLogin');localStorage.removeItem(KEY);localStorage.removeItem(CLOUD_ACCOUNT_KEY);if(typeof groupReset==='function')groupReset();cloudUser=null;state=structuredClone(seed)}
function cleanAppUrl(){const url=new URL(location.href);let changed=false;for(const key of ['account','session'])if(url.searchParams.has(key)){url.searchParams.delete(key);changed=true}if(changed)history.replaceState({},'',`${url.pathname}${url.search}${url.hash}`)}
function redirectWithNotice(message){sessionStorage.setItem(NOTICE_KEY,message);location.replace(`${location.origin}${location.pathname}`)}
async function invalidateCloudSession(message='Your session is no longer valid. Please create an account or sign in again.'){if(invalidatingSession)return;invalidatingSession=true;try{await sb?.auth.signOut({scope:'local'})}catch{}clearClientAccount();redirectWithNotice(message)}
function localAppearance(){try{return JSON.parse(localStorage.getItem(APPEARANCE_KEY)||'null')}catch{return null}}
function appearanceSnapshot(settings=state.settings){return Object.fromEntries(['theme','fontStyle','textScale','loginImage','loginImagePosition','loginImageShade'].map(key=>[key,settings?.[key]??seed.settings[key]]))}
function rememberAppearance(settings=state.settings){try{localStorage.setItem(APPEARANCE_KEY,JSON.stringify(appearanceSnapshot(settings)))}catch{toast('The custom login image is too large for this browser')}}
function applyTheme(useProfile=false){const local=localAppearance(),s={...seed.settings,...state.settings,...(!useProfile&&local?local:{})};document.body.classList.remove('theme-nestlyra','theme-cyber','theme-matrix','theme-ocean','theme-light');let theme=s.theme;if(theme==='auto')theme=matchMedia('(prefers-color-scheme: light)').matches?'nestlyra':'dark';if(theme&&theme!=='dark')document.body.classList.add(`theme-${theme}`);document.body.dataset.fontStyle=s.fontStyle||'modern';document.body.dataset.textScale=s.textScale||'normal';document.body.dataset.loginShade=s.loginImageShade||'balanced';const positions={left:'30% 34%',center:'center 34%',right:'70% 34%'};document.documentElement.style.setProperty('--login-position',positions[s.loginImagePosition]||positions.center);if(s.loginImage)document.documentElement.style.setProperty('--login-image',`url("${s.loginImage}")`);else document.documentElement.style.removeProperty('--login-image');if(useProfile)rememberAppearance(s)}
function beep(){if(!state.settings.sounds)return;try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=520;g.gain.setValueAtTime(.08,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.18);o.start();o.stop(c.currentTime+.18)}catch{}}
async function login(e){e.preventDefault();if(typeof familyPrepareLearnerLogin==='function')familyPrepareLearnerLogin();const name=loginName.value.trim(),pin=loginPin.value;if(sb&&name.includes('@')){const button=e.submitter;button.disabled=true;button.textContent='Signing in…';try{const result=await sb.auth.signInWithPassword({email:name,password:pin});if(result.error)throw Error('Account not found or password incorrect. Use Create new account if this account was deleted.');cloudUser=result.data.user;if(typeof familyResolveAuthenticatedRole==='function')await familyResolveAuthenticatedRole(cloudUser);await loadCloud();showApp()}catch(error){await sb.auth.signOut({scope:'local'});cloudUser=null;toast(error.message||'Sign-in failed')}finally{button.disabled=false;button.innerHTML='Sign in <span>→</span>'}return}if(!state.profile)return toast('No local account exists. Use Create new account.');if(state.profile.name.toLowerCase()!==name.toLowerCase()||state.profile.pin!==pin)return toast('Incorrect local name or PIN');showApp()}
async function createLearnerAccount(){if(typeof familyPrepareLearnerLogin==='function')familyPrepareLearnerLogin();const name=loginName.value.trim(),pin=loginPin.value;if(!name||pin.length<4)return toast('Enter a name or email and a password of at least 4 characters');createLearnerAccountBtn.disabled=true;createLearnerAccountBtn.textContent='Creating account…';try{if(sb&&name.includes('@')){const {data,error}=await sb.auth.signUp({email:name,password:pin,options:{data:{full_name:name.split('@')[0]}}});if(error)throw error;if(!data.session)return toast('Check your email to confirm the new account, then sign in.');cloudUser=data.user;if(typeof familyResolveAuthenticatedRole==='function')await familyResolveAuthenticatedRole(cloudUser);await loadCloud();showApp();return}if(state.profile)throw Error('A local account already exists. Sign in or delete it from Settings.');state.profile={name,pin};save();showApp()}catch(error){try{await sb?.auth.signOut({scope:'local'})}catch{}cloudUser=null;toast(error.message||'Account could not be created')}finally{createLearnerAccountBtn.disabled=false;createLearnerAccountBtn.textContent='Create new account'}}
function showApp(){if(cloudUser)markCloudAccount();restoreView();applyTheme(true);document.documentElement.classList.remove('session-pending');authScreen.classList.add('hidden');app.classList.remove('hidden');avatar.textContent=(state.profile?.name||'P')[0].toUpperCase();rememberView();updateViewHistory(viewName,{replace:true});render();if(typeof familyOnAppShown==='function')familyOnAppShown();if(typeof familyScheduleBriefing==='function')familyScheduleBriefing();else setTimeout(welcomeBriefing,300)}
function welcomeBriefing(){const d=document.querySelector('#modal');if(d.open)return;const name=escapeHtml((state.profile?.name||cloudUser?.user_metadata?.full_name||'Learner').split(' ')[0]),pending=state.tasks.filter(t=>t.status!=='completed'),overdue=pending.filter(t=>t.due&&t.due<today()),todayTasks=pending.filter(t=>t.due===today()),todayTopics=allTopics().filter(t=>t.status!=='completed'&&t.due===today()),upcoming=allTopics().filter(t=>t.status!=='completed'&&t.due>today()).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5),jobs=state.jobApplications||[],followUps=jobs.filter(jobDue),interviews=jobs.filter(j=>j.status==='Interview').length,positive=jobs.filter(j=>['Selected','Offer'].includes(j.status)).length;const plan=[...todayTasks.map(t=>({title:t.title,meta:`Task · ${t.time||'Any time'}`})),...todayTopics.map(t=>({title:t.name,meta:`Topic · ${t.subject}`}))].slice(0,5);modal(`<div class="briefing"><span class="eyebrow">DAILY BRIEFING</span><h2>Welcome back, ${name}</h2><p class="briefing-date">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p><div class="briefing-stats"><div class="${overdue.length?'attention':''}"><strong>${overdue.length}</strong><span>Overdue</span></div><div><strong>${plan.length}</strong><span>Today</span></div><div><strong>${upcoming.length}</strong><span>Upcoming</span></div><div class="${followUps.length?'attention':''}"><strong>${followUps.length}</strong><span>Job follow-ups</span></div></div><section><div class="card-title"><h3>Today's plan</h3><span>${plan.length} item${plan.length===1?'':'s'}</span></div>${plan.length?`<div class="briefing-list">${plan.map(x=>`<div><b>${escapeHtml(x.title)}</b><small>${escapeHtml(x.meta)}</small></div>`).join('')}</div>`:'<div class="briefing-empty">Nothing planned for today.</div>'}</section><section><div class="card-title"><h3>Coming up</h3><span>Next topics</span></div>${upcoming.length?`<div class="briefing-list">${upcoming.map(x=>`<div><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.subject)} · ${x.due}</small></div>`).join('')}</div>`:'<div class="briefing-empty">No upcoming topic deadlines.</div>'}</section><section class="job-brief"><div><h3>Job Tracker</h3><p>${jobs.length} applications · ${interviews} interviews · ${positive} selected/offers</p></div><strong class="${followUps.length?'due':''}">${followUps.length?`${followUps.length} follow-up${followUps.length===1?'':'s'} due`:'No follow-ups due'}</strong></section><div class="modal-actions"><button type="button" class="btn ghost" onclick="openBriefingView('jobs')">Job Tracker</button><button type="button" class="btn ghost" onclick="openBriefingView('calendar')">Open calendar</button><button type="button" class="btn primary" onclick="closeModal()">Start my day</button></div></div>`)}
window.openBriefingView=n=>{closeModal();setView(n)};
function head(title,sub,action=''){return `<div class="page-head"><div><span class="eyebrow">NESTLYRA FOCUS</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function taskRows(tasks){if(!tasks.length)return '<div class="empty">No tasks here yet.</div>';return `<div class="task-list">${tasks.map(t=>{const overdue=t.due&&t.due<today()&&t.status!=='completed';return `<div class="task-row ${t.status==='completed'?'done':''}"><button class="check ${t.status==='completed'?'checked':''}" onclick="toggleTask('${t.id}')">${t.status==='completed'?'✓':''}</button><div><div class="task-name">${escapeHtml(t.title)}</div><div class="task-meta">${escapeHtml(subjectName(t.subjectId))} · ${t.due||'No date'} ${t.time||''}</div></div><div class="row-actions"><span class="badge ${overdue?'danger':t.priority==='high'?'warn':''}">${overdue?'Overdue':t.priority}</span><button class="mini-btn" title="Edit task" onclick="taskModal('${t.id}')">✎</button><button class="mini-btn" title="Delete task" onclick="deleteTask('${t.id}')">×</button></div></div>`}).join('')}</div>`}
function dashboard(){setTimeout(drawCharts);const p=overall(),due=state.tasks.filter(t=>t.status!=='completed'&&t.due===today()),completed=allTopics().filter(t=>t.status==='completed').length;return head(`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${escapeHtml(state.profile.name.split(' ')[0])}`,"Your study progress and analytics in one place")+`<div class="grid stats"><div class="stat"><div class="stat-icon">◫</div><div><small>Total subjects</small><strong>${state.subjects.length}</strong></div></div><div class="stat"><div class="stat-icon">✓</div><div><small>Topics completed</small><strong>${completed}</strong></div></div><div class="stat"><div class="stat-icon">◷</div><div><small>Due today</small><strong>${due.length}</strong></div></div><div class="stat"><div class="stat-icon">⌁</div><div><small>Study hours</small><strong>${Math.round(state.activity.reduce((a,x)=>a+x.minutes,0)/60)}h</strong></div></div></div><div class="grid dashboard-grid"><section class="card span-2"><div class="card-title"><h3>Overall progress</h3><span>All subjects</span></div><div class="overview-flex"><div class="progress-ring" style="--p:${p}"><div><strong>${p}%</strong><small>completed</small></div></div><div class="subject-bars">${state.subjects.slice(0,5).map(s=>`<div class="bar-row"><span>${escapeHtml(s.name)}</span><div class="bar"><i style="width:${pct(s)}%"></i></div><b>${pct(s)}%</b></div>`).join('')}</div></div></section><section class="card"><div class="card-title"><h3>Subject progress analytics</h3><span>Completion %</span></div><div class="chart-box"><canvas id="progressChart"></canvas></div></section><section class="card"><div class="card-title"><h3>Status distribution</h3><span>${streak()} day streak</span></div><div class="chart-box"><canvas id="statusChart"></canvas></div></section><section class="card span-2"><div class="card-title"><h3>Upcoming deadlines</h3><button class="kebab" onclick="setView('calendar')">Calendar →</button></div>${taskRows(state.tasks.filter(t=>t.status!=='completed').sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,5))}</section></div>`}
function subjects(){return head('My subjects','Manage all your learning tracks','<button class="btn primary" onclick="subjectModal()">+ Add subject</button>')+`<div class="grid subject-grid">${state.subjects.map(s=>`<article class="card subject-card" style="--subject:${s.color}" onclick="openSubject('${s.id}')"><div class="subject-top"><div class="subject-icon">${escapeHtml(s.icon)}</div><button class="kebab" onclick="event.stopPropagation();subjectModal('${s.id}')">•••</button></div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.description)}</p><div class="progress-line"><i style="width:${pct(s)}%"></i></div><div class="progress-label"><span>${s.modules.length} modules</span><strong>${pct(s)}%</strong></div></article>`).join('')}</div>`}
function subjectView(){const s=state.subjects.find(x=>x.id===selectedSubject)||state.subjects[0];if(!s)return subjects();return head(`${escapeHtml(s.name)} tracker`,escapeHtml(s.description),`<button class="btn primary" onclick="moduleModal('${s.id}')">+ Add module</button>`)+`<div class="grid stats"><div class="stat"><div><small>Overall progress</small><strong>${pct(s)}%</strong></div></div><div class="stat"><div><small>Modules</small><strong>${s.modules.length}</strong></div></div><div class="stat"><div><small>Topics</small><strong>${s.modules.flatMap(m=>m.topics).length}</strong></div></div><div class="stat"><div><small>Completed</small><strong>${s.modules.flatMap(m=>m.topics).filter(t=>t.status==='completed').length}</strong></div></div></div><div class="grid">${s.modules.map((m,i)=>`<section class="card module"><div class="module-head"><h3>${i+1}. ${escapeHtml(m.name)}</h3><button class="btn ghost" onclick="topicModal('${s.id}','${m.id}')">+ Topic</button></div><div class="module-body">${m.topics.length?m.topics.map(t=>`<div class="subtopic-row"><button class="check ${t.status==='completed'?'checked':''}" onclick="cycleTopic('${s.id}','${m.id}','${t.id}')">${t.status==='completed'?'✓':''}</button><span>${escapeHtml(t.name)}</span><select onchange="topicStatus('${s.id}','${m.id}','${t.id}',this.value)"><option value="not-started" ${t.status==='not-started'?'selected':''}>Not started</option><option value="in-progress" ${t.status==='in-progress'?'selected':''}>In progress</option><option value="completed" ${t.status==='completed'?'selected':''}>Completed</option></select><input type="date" value="${t.due||''}" onchange="topicDue('${s.id}','${m.id}','${t.id}',this.value)"><button class="kebab" onclick="deleteTopic('${s.id}','${m.id}','${t.id}')">×</button></div>`).join(''):'<div class="empty">No topics in this module.</div>'}</div></section>`).join('')}</div>`}
function todayView(){const due=state.tasks.filter(t=>t.due===today());return head('Today plan',new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}),'<button class="btn primary" onclick="taskModal()">+ New task</button>')+`<section class="card">${taskRows(due)}</section>`}
