function analytics(){setTimeout(drawCharts);const completed=allTopics().filter(t=>t.status==='completed').length;return head('Progress analytics','Understand your momentum and consistency')+`<div class="grid stats"><div class="stat"><div><small>Study hours</small><strong>${Math.round(state.activity.reduce((a,x)=>a+x.minutes,0)/60)}</strong></div></div><div class="stat"><div><small>Topics completed</small><strong>${completed}</strong></div></div><div class="stat"><div><small>Accuracy</small><strong>${overall()}%</strong></div></div><div class="stat"><div><small>Current streak</small><strong>${streak()} days</strong></div></div></div><div class="grid analytics-grid"><section class="card"><div class="card-title"><h3>Subject progress</h3></div><div class="chart-box"><canvas id="progressChart"></canvas></div></section><section class="card"><div class="card-title"><h3>Status distribution</h3></div><div class="chart-box"><canvas id="statusChart"></canvas></div></section></div>`}
let progressChartInstance=null,statusChartInstance=null;
function drawCharts(){const progressCanvas=document.getElementById('progressChart'),statusCanvas=document.getElementById('statusChart');if(!window.Chart||!progressCanvas||!statusCanvas)return;progressChartInstance?.destroy();statusChartInstance?.destroy();Chart.defaults.color='#8493a9';progressChartInstance=new Chart(progressCanvas,{type:'bar',data:{labels:state.subjects.map(s=>s.name),datasets:[{data:state.subjects.map(pct),backgroundColor:state.subjects.map(s=>s.color),borderRadius:8}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,max:100,grid:{color:'#1d2c42'}},x:{grid:{display:false}}}}});const t=allTopics();statusChartInstance=new Chart(statusCanvas,{type:'doughnut',data:{labels:['Completed','In progress','Not started'],datasets:[{data:['completed','in-progress','not-started'].map(x=>t.filter(y=>y.status===x).length),backgroundColor:['#35d07f','#7c5cff','#29384d'],borderWidth:0}]},options:{maintainAspectRatio:false,cutout:'70%'}})}
function notes(){let n=state.notes.find(x=>x.id===selectedNote)||state.notes[0];return head('Notes','Keep methodology, commands and revision notes together','<button class="btn primary" onclick="newNote()">+ New note</button>')+`<div class="grid note-layout"><aside class="card note-list">${state.notes.map(x=>`<button class="note-item ${x.id===n?.id?'active':''}" onclick="selectNote('${x.id}')"><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(subjectName(x.subjectId))} · ${x.updated}</small></button>`).join('')}</aside><section class="card note-editor">${n?`<input value="${escapeHtml(n.title)}" oninput="editNote('title',this.value)"><textarea oninput="editNote('content',this.value)">${escapeHtml(n.content)}</textarea><div class="modal-actions"><button class="btn danger" onclick="deleteNote('${n.id}')">Delete note</button></div>`:'<div class="empty">Create your first note.</div>'}</section></div>`}
function calendar(){const y=calDate.getFullYear(),m=calDate.getMonth(),first=new Date(y,m,1),start=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),prev=new Date(y,m,0).getDate(),todayTasks=state.tasks.filter(t=>t.due===today());let cells='';for(let i=0;i<42;i++){let d,muted=false,month=m;if(i<start){d=prev-start+i+1;month=m-1;muted=true}else if(i>=start+days){d=i-start-days+1;month=m+1;muted=true}else d=i-start+1;const iso=new Date(y,month,d,12).toISOString().slice(0,10),items=[...state.tasks.filter(t=>t.due===iso).map(t=>({...t,kind:'task'})),...(state.events||[]).filter(e=>e.date===iso).map(e=>({...e,kind:'event'})),...allTopics().filter(t=>t.due===iso).map(t=>({id:t.id,title:t.name,kind:'topic'})),...(state.jobApplications||[]).filter(a=>a.followUpDate===iso&&!jobTerminal(a.status)).map(a=>({id:a.id,title:`Follow up: ${a.company}`,kind:'job'}))];cells+=`<button class="cal-day ${muted?'muted':''} ${iso===today()?'today':''}" onclick="calendarDay('${iso}')"><span class="cal-num">${d}</span>${items.slice(0,3).map(e=>`<span class="cal-event ${e.kind}">${escapeHtml(e.title)}</span>`).join('')}${items.length>3?`<small>+${items.length-3} more</small>`:''}</button>`}return head('Calendar & today plan','Study deadlines, today tasks, events and job follow-ups',`<div class="job-head-actions"><button class="btn ghost" onclick="taskModal()">+ Today task</button><button class="btn primary" onclick="eventModal()">+ Add event</button></div>`)+`<div class="grid calendar-layout"><section class="card calendar-card"><div class="calendar-head"><button class="icon-btn" onclick="moveMonth(-1)">‹</button><button class="btn ghost" onclick="calDate=new Date();render()">Today</button><h3>${calDate.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h3><button class="icon-btn" onclick="moveMonth(1)">›</button></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="day-name">${x}</div>`).join('')}${cells}</div></section><aside class="card today-panel"><div class="card-title"><h3>Today plan</h3><span>${todayTasks.length} task${todayTasks.length===1?'':'s'}</span></div>${taskRows(todayTasks)}</aside></div>`}
function settings(){const themes=[['dark','#7c5cff'],['cyber','#ff3e9d'],['matrix','#3cdb71'],['ocean','#1b9cff'],['light','#dce8f5']];return head('User & app settings','Your complete account and application control center')+`<div class="grid settings-grid"><section class="card"><div class="card-title"><h3>Profile & security</h3></div><div class="setting-row"><span>Signed in as</span><strong>${escapeHtml(state.profile?.name||'Local user')}</strong></div><div class="setting-row"><span>Account email</span><strong>${escapeHtml(state.profile?.email||cloudUser?.email||'Local profile')}</strong></div><div class="modal-actions"><button class="btn ghost" onclick="signOut()">↪ Sign out</button><button class="btn primary" onclick="profileModal()">Edit profile / password</button></div></section><section class="card"><div class="card-title"><h3>Workspace control</h3><span>${state.workspaces.length} total</span></div><label class="workspace-switcher settings-workspace">Active workspace<select id="settingsWorkspaceSelect" aria-label="Current workspace" onchange="switchWorkspace(this.value)">${state.workspaces.filter(w=>!w.archived||w.id===state.activeWorkspace).map(w=>`<option value="${w.id}" ${w.id===state.activeWorkspace?'selected':''}>${escapeHtml(w.name)}</option>`).join('')}</select></label>${state.workspaces.map(w=>`<div class="setting-row"><span>${escapeHtml(w.name)} ${w.archived?'(Archived)':''}</span><button class="mini-btn" onclick="workspaceModal('${w.id}')">✎</button></div>`).join('')}<div class="modal-actions"><button class="btn primary" onclick="workspaceModal()">+ New workspace</button></div></section><section class="card"><div class="card-title"><h3>Appearance</h3></div><div class="theme-list">${themes.map(([n,c])=>`<button title="${n}" class="theme-chip ${state.settings.theme===n?'active':''}" style="--swatch:${c}" onclick="setTheme('${n}')"></button>`).join('')}</div></section><section class="card"><div class="card-title"><h3>Sound & notifications</h3></div><div class="setting-row"><span>Completion sound</span><button class="toggle ${state.settings.sounds?'on':''}" onclick="toggleSetting('sounds')"></button></div><div class="setting-row"><span>Deadline notifications</span><button class="toggle ${state.settings.notifications?'on':''}" onclick="toggleSetting('notifications')"></button></div></section><section class="card"><div class="card-title"><h3>Subjects import / export</h3></div><p class="task-meta">Choose one or several subjects. Only their modules and topics are exported; tasks, jobs, notes, events, profile and settings are never included.</p><div class="modal-actions"><button class="btn ghost" onclick="importInput.click()">Import subjects</button><button class="btn ghost" onclick="exportJSON()">Choose subjects to export</button><button class="btn primary" onclick="downloadSubjectTemplate()">Sample JSON</button></div></section><section class="card"><div class="card-title"><h3>Account control</h3></div><p class="task-meta">Permanently delete this account and its tracker data.</p><div class="modal-actions"><button class="btn danger" onclick="deleteAccountModal()">Delete account</button></div></section></div>`}
function timerView(){const mins=String(Math.floor(timerSeconds/60)).padStart(2,'0'),secs=String(timerSeconds%60).padStart(2,'0');return head('Study timer','Complete focused sessions and automatically record study time')+`<section class="card timer-shell"><span class="eyebrow">FOCUS SESSION</span><div id="timerDisplay" class="timer-display">${mins}:${secs}</div><div class="timer-presets"><button class="btn ghost" onclick="setTimer(25)">25 min</button><button class="btn ghost" onclick="setTimer(45)">45 min</button><button class="btn ghost" onclick="setTimer(60)">60 min</button></div><p id="timerStatus" class="timer-status">${timerHandle?'Session running':'Ready when you are'}</p><div class="timer-actions"><button class="btn primary" onclick="startTimer()">▶ Start</button><button class="btn ghost" onclick="pauseTimer()">Pause</button><button class="btn danger" onclick="resetTimer()">Reset</button></div></section>`}
function manualSection(id,icon,title,summary,content,open=false){return `<details id="manual-${id}" class="card manual-section" ${open?'open':''}><summary><span class="manual-icon">${icon}</span><span><strong>${title}</strong><small>${summary}</small></span><i>+</i></summary><div class="manual-body">${content}</div></details>`}
function helpView(){return head('Help & user manual','Complete guidance for setup, daily use, Family monitoring and account security',`<button class="btn ghost" onclick="loginFaqModal()">Login FAQ</button>`)+`<section class="card manual-start"><div><span class="eyebrow">QUICK START</span><h2>Start using Nestlyra Focus in four steps</h2><p>Create the correct role, organize a subject, schedule the work, then review progress every day.</p></div><div class="manual-steps"><button onclick="scrollManual('setup')"><b>1</b><span>Create account</span></button><button onclick="scrollManual('subjects')"><b>2</b><span>Add subjects</span></button><button onclick="scrollManual('planning')"><b>3</b><span>Plan dates</span></button><button onclick="scrollManual('daily')"><b>4</b><span>Study & review</span></button></div></section><label class="manual-search">⌕ <input aria-label="Search the user manual" placeholder="Search calendar, extension, resume, parent, messages…" oninput="filterManual(this.value)"></label><div class="manual-layout"><aside class="card manual-nav"><strong>Manual contents</strong>${[['setup','First setup'],['daily','Dashboard & briefing'],['subjects','Subjects & progress'],['planning','Tasks & calendar'],['notes','Notes & timer'],['jobs','Job Tracker'],['workspaces','Settings & workspaces'],['family','Parent / Admin'],['transfer','Import / export'],['security','Account & security'],['faq','Common questions']].map(([id,label])=>`<button onclick="scrollManual('${id}')">${label}<span>→</span></button>`).join('')}</aside><div class="manual-content">${manualSection('setup','01','First setup and account choice','Choose Learner or Parent/Admin before entering data.',`<ol><li>On the login screen choose <strong>Learner login</strong> for the normal Nestlyra Focus or <strong>Parent / Admin</strong> for monitoring.</li><li>For cloud sync, enter an email and password and select <strong>Create new account</strong>, or continue with Google. Existing users should select <strong>Sign in</strong>.</li><li>For offline-only use, enter a name and local PIN. Local information stays in that browser and does not automatically appear on another device.</li><li>A new Learner receives one sample subject containing five modules and five topics per module. Edit or delete it after understanding the structure.</li><li>Do not use one cloud account for both roles. Learner and Parent/Admin accounts must be separate.</li></ol>`,true)+manualSection('daily','02','Dashboard and daily briefing','See progress, deadlines, study time and today’s priorities.',`<ul><li>The welcome briefing shows overdue work, today’s plan, upcoming topics and Job Tracker updates.</li><li>Select <strong>Start my day</strong> to close it, use the × button, or click outside the dialog. Closing it cancels any scheduled voice reading.</li><li>Dashboard cards summarize subjects, completed topics, tasks due today and recorded study hours.</li><li>Progress charts update when topic statuses change. Upcoming deadlines come from tasks and topic due dates.</li><li>The notification icon summarizes overdue tasks and job follow-ups. The profile avatar opens Settings.</li></ul>`)+manualSection('subjects','03','Subjects, modules and topics','Build a complete course hierarchy and track every topic.',`<ol><li>Open <strong>Subjects</strong> and select <strong>Add subject</strong>. Enter a name, short icon, description and color.</li><li>Open the subject card and add modules, then add topics inside each module.</li><li>Give topics a due date and choose Not started, In progress or Completed. The check button cycles progress quickly.</li><li>Subject cards and Dashboard analytics calculate completion from topic statuses.</li><li>Use the subject menu to edit its details. Deleting a subject also deletes its modules and topics, so confirm carefully.</li></ol>`)+manualSection('planning','04','Tasks, Calendar and Today plan','Schedule study work, events and follow-ups without overlap.',`<ul><li><strong>Tasks:</strong> create a title, subject, priority, date and time. Use the edit icon to change it later and the check control to complete it.</li><li><strong>Calendar:</strong> use the previous/next arrows, Today, and the Day, Week or Month tabs. Select a month date to open its day timeline, then add or edit events.</li><li>The Calendar combines tasks, custom events, topic deadlines and active job follow-up dates.</li><li>Switch between Month, Week and Day. Category filters let you show or hide tasks, study deadlines, exams, events and job follow-ups without deleting data.</li><li>Completed tasks remain available for history; delete only when you no longer need the record.</li></ul>`)+manualSection('notes','05','Notes and Study Timer','Keep revision material together and record focused sessions.',`<ul><li>Create notes for commands, methodology, revision summaries or interview preparation. Select a note on the left and edit the title or content directly.</li><li>Notes save with the active workspace. Deleting a note cannot be undone.</li><li>Open Study Timer from the sidebar. Choose 25, 45 or 60 minutes, then Start, Pause or Reset.</li><li>A completed timer session is added to study activity and contributes to Dashboard study hours.</li><li>The analog clock opens Calendar; the flame displays the current study streak.</li></ul>`)+manualSection('jobs','06','Job Application Tracker','Preserve every application even after the posting disappears.',`<ol><li>Select <strong>Add application</strong> and save company, role, job ID, platform, dates, status, location, salary, contact and original link.</li><li>Paste the complete job description or upload a PDF, DOCX or TXT JD. You may also attach a tailored resume and cover letter, up to 10 MB each.</li><li>Open any application to change status, set a follow-up, view the preserved JD, download documents, duplicate the record or edit missing details.</li><li>Search by role, company, ID, notes or JD; filter by status or follow-up due; sort by newest, oldest or company.</li><li>CSV export exports the filtered application list. The Browser extension downloads separately; captured details are always shown as a draft for review before saving.</li></ol>`)+manualSection('workspaces','07','Settings, profile and workspaces','Control appearance, sound, voice and separate study areas.',`<ul><li>Select the profile avatar to open Settings. Update the display name or password, change theme, completion sound and notifications.</li><li>Create a workspace for each learner, certification or fresh study cycle. Switching workspaces changes subjects, tasks, events, notes and jobs together.</li><li>Archive a workspace to hide it temporarily. Delete only when its stored data is no longer required.</li><li>Voice settings provide five voice profiles, speaking speed, automatic briefing, Test voice and Stop controls.</li><li>Family access, today’s tracked time and screen changes are also shown in Learner Settings.</li></ul>`)+manualSection('family','08','Parent / Admin linking and monitoring','Connect separate accounts using a temporary code.',`<ol><li>The Parent signs in through <strong>Parent / Admin</strong> using a separate email/Google account or protected local Parent ID.</li><li>In the Parent Dashboard select <strong>Generate linking code</strong>. The code is single-use and expires after 15 minutes.</li><li>The Learner opens Settings, enters that code under Family access and selects <strong>Link Parent/Admin</strong>.</li><li>The Parent Observer can then see online or last-seen status, focused time, idle time, screen changes, section usage, subjects, modules, topics, tasks, events and optional Job Tracker records. The app never records keystrokes or activity outside Nestlyra Focus.</li><li>The Parent may review learning and plans without editing learner data, unlink a learner, clear activity history, sign out or permanently delete the Parent account.</li></ol>`)+manualSection('transfer','09','Subject import and export','Transfer course structure only—never personal or unrelated data.',`<ul><li>Settings → Subjects import/export handles only subjects, modules, topics, statuses and topic due dates.</li><li>Select <strong>Sample JSON</strong> when you need the correct structure, especially in an empty workspace.</li><li><strong>Export subjects</strong> downloads only course data. It never exports tasks, calendar events, jobs, notes, documents, profile, Family activity or settings.</li><li><strong>Import subjects</strong> validates the JSON and adds valid subjects to the current workspace without replacing existing ones.</li><li>Job applications use their own CSV export inside Job Tracker.</li></ul>`)+manualSection('security','10','Sign out, sync and permanent deletion','Understand what remains local, what syncs, and what deletion does.',`<ul><li>Cloud accounts sync tracker data through Supabase. Local accounts remain on the current browser/device.</li><li><strong>Sign out</strong> ends the current session and returns to login. Use the same account to access cloud data again.</li><li><strong>Delete account</strong> requires typing DELETE. It permanently removes the authentication account and related tracker/Family data.</li><li>A deleted account cannot reopen from cached browser data. The app validates cloud accounts on startup, tab focus, visibility changes and every 30 seconds.</li><li>After deletion, Sign in will fail. Select Create new account if you intentionally want a completely new account.</li></ul>`)+manualSection('faq','11','Frequently asked questions','Answers to the most common setup and usage problems.',`<div class="faq-list"><details><summary>Why do I see a sample course?</summary><p>It teaches the Subject → Module → Topic structure. Edit it, import your own subjects, or delete it when ready.</p></details><details><summary>Why can’t the same Google account be both Learner and Parent?</summary><p>Each cloud identity has one protected role. Use a different Parent/Admin account, then link it with a temporary code.</p></details><details><summary>Why is a document unavailable on another device?</summary><p>New attachments are intentionally stored in the original browser’s IndexedDB. The application record may sync, but the local file does not; Google Drive sync is planned.</p></details><details><summary>Does Parent mode monitor my whole computer?</summary><p>No. It records only Nestlyra Focus focused/idle time, section usage, screen changes and login activity.</p></details><details><summary>Will import/export expose my jobs or profile?</summary><p>No. Subject import/export is intentionally limited to subject, module and topic data.</p></details><details><summary>What happens after account deletion?</summary><p>The login and related cloud data are removed. Cached data is cleared and the account must be created again before it can be used.</p></details></div>`)}</div></div>`}
window.scrollManual=id=>{const section=document.getElementById(`manual-${id}`);if(!section)return;section.open=true;section.scrollIntoView({behavior:'smooth',block:'start'})};
window.filterManual=query=>{const q=String(query||'').trim().toLowerCase();document.querySelectorAll('.manual-section').forEach(section=>{section.hidden=Boolean(q&&!section.innerText.toLowerCase().includes(q));if(q&&!section.hidden)section.open=true})};
window.loginFaqModal=()=>modal(`<div class="login-faq"><span class="eyebrow">LOGIN & ROLE GUIDE</span><h2>How to access Nestlyra Focus</h2><p>Choose the role and sign-in method that matches how you will use the application.</p><div class="login-guide-grid"><section><b>LEARNER</b><h3>Normal Nestlyra Focus</h3><ol><li>Stay on Learner login.</li><li>Existing account: enter credentials and select Sign in.</li><li>New account: enter details and select Create new Learner account.</li><li>Or use Continue with Google.</li></ol></section><section><b>PARENT / ADMIN</b><h3>Monitoring portal</h3><ol><li>Open Parent / Admin.</li><li>Use a separate Parent email, Google account or local Parent ID.</li><li>Generate a linking code after login.</li><li>Enter that code in the Learner’s Settings.</li></ol></section></div><div class="faq-list"><details open><summary>What is the difference between Sign in and Create account?</summary><p>Sign in opens an existing account only. Create account makes a new identity. A deleted account is never recreated automatically by Sign in.</p></details><details><summary>Can one account be both Learner and Parent/Admin?</summary><p>No. Use separate cloud accounts for the two roles, then connect them with a temporary Family code.</p></details><details><summary>Can I use Nestlyra Focus without Google?</summary><p>Yes. Use email and password for cloud sync, or a name/local PIN for offline use on one device.</p></details><details><summary>How does Parent linking work?</summary><p>The Parent generates a single-use code valid for 15 minutes. The Learner enters it in Settings → Family access.</p></details><details><summary>Why did login return me to this screen?</summary><p>The credentials may be incorrect, the selected role may not match the account, or the account may have been deleted. Choose the correct tab and use Create account only when you want a new account.</p></details><details><summary>Will refreshing restore a deleted account?</summary><p>No. Nestlyra Focus verifies the account with Supabase and clears invalid cached sessions.</p></details></div><div class="modal-actions"><button class="btn primary">Close guide</button></div></div>`);
function render(){sideStreak.textContent=`${streak()} days`;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===viewName));const views={dashboard,subjects,tasks:tasksView,notes,calendar,jobs:jobTracker,messages:window.familyMessagingView,timer:timerView,settings,help:helpView,subject:subjectView};view.innerHTML=(views[viewName]||dashboard)();if(viewName==='settings'&&typeof enhanceSettingsNavigation==='function')setTimeout(enhanceSettingsNavigation)}
window.setView=(n,options={})=>{viewName=n;rememberView(n);setNavigationOpen(false);if(!options.fromHistory)updateViewHistory(n,{replace:Boolean(options.replace)});render()};window.openSubject=id=>{selectedSubject=id;viewName='subject';rememberView('subject');setNavigationOpen(false);updateViewHistory('subject');render()};
function modal(html){modalBody.innerHTML=html;const d=document.querySelector('#modal');if(!d.open)d.showModal()}function closeModal(){document.querySelector('#modal').close()}function field(id){return document.getElementById(id)}
window.subjectModal=id=>{const s=state.subjects.find(x=>x.id===id);modal(`<h2>${s?'Edit':'Add'} subject</h2><div class="form-grid"><label>Name<input id="fName" value="${escapeHtml(s?.name||'')}"></label><label>Short icon<input id="fIcon" maxlength="3" value="${escapeHtml(s?.icon||'')}"></label><label class="full">Description<input id="fDesc" value="${escapeHtml(s?.description||'')}"></label><label>Color<input id="fColor" type="color" value="${s?.color||'#7c5cff'}"></label></div><div class="modal-actions">${s?'<button type="button" class="btn danger" onclick="deleteSubject(\''+s.id+'\')">Delete</button>':''}<button class="btn ghost">Cancel</button><button type="button" class="btn primary" onclick="saveSubject('${id||''}')">Save</button></div>`)};
window.saveSubject=id=>{const s=state.subjects.find(x=>x.id===id),name=field('fName').value.trim(),data={name,icon:(field('fIcon').value||name.slice(0,2)).toUpperCase(),description:field('fDesc').value.trim(),color:field('fColor').value};if(!data.name)return toast('Subject name is required');if(s)Object.assign(s,data);else state.subjects.push({id:uid(),...data,modules:[]});save();closeModal();render();toast('Subject saved')};
window.deleteSubject=id=>{if(!confirm('Delete this subject and all its modules?'))return;state.subjects=state.subjects.filter(s=>s.id!==id);save();closeModal();viewName='subjects';render()};
window.moduleModal=sid=>modal(`<h2>Add module</h2><label>Module name<input id="fModule"></label><div class="modal-actions"><button class="btn ghost">Cancel</button><button type="button" class="btn primary" onclick="saveModule('${sid}')">Add module</button></div>`);
window.saveModule=sid=>{const s=state.subjects.find(x=>x.id===sid),name=field('fModule').value.trim();if(!name)return toast('Module name is required');s.modules.push({id:uid(),name,topics:[]});save();closeModal();render();toast('Module added')};
window.topicModal=(sid,mid)=>modal(`<h2>Add topic</h2><div class="form-grid"><label class="full">Topic name<input id="fTopic"></label><label>Due date<input id="fDue" type="date"></label><label>Status<select id="fStatus"><option value="not-started">Not started</option><option value="in-progress">In progress</option><option value="completed">Completed</option></select></label></div><div class="modal-actions"><button class="btn ghost">Cancel</button><button type="button" class="btn primary" onclick="saveTopic('${sid}','${mid}')">Add topic</button></div>`);
function getTopic(sid,mid,tid){return state.subjects.find(s=>s.id===sid)?.modules.find(m=>m.id===mid)?.topics.find(t=>t.id===tid)}
window.saveTopic=(sid,mid)=>{const m=state.subjects.find(s=>s.id===sid).modules.find(x=>x.id===mid),name=field('fTopic').value.trim();if(!name)return toast('Topic name is required');m.topics.push({id:uid(),name,due:field('fDue').value,status:field('fStatus').value});save();closeModal();render();toast('Topic added')};
window.topicStatus=(s,m,t,v)=>{getTopic(s,m,t).status=v;save();render()};window.topicDue=(s,m,t,v)=>{getTopic(s,m,t).due=v;save()};window.cycleTopic=(s,m,t)=>{const x=getTopic(s,m,t);x.status=x.status==='completed'?'not-started':'completed';save();if(x.status==='completed')beep();render()};window.deleteTopic=(s,m,t)=>{const x=state.subjects.find(x=>x.id===s).modules.find(x=>x.id===m);x.topics=x.topics.filter(x=>x.id!==t);save();render()};
window.taskModal=id=>{const t=state.tasks.find(x=>x.id===id);modal(`<h2>${t?'Edit':'New'} study task</h2><div class="form-grid"><label class="full">Task title<input id="fTask" value="${escapeHtml(t?.title||'')}"></label><label>Subject<select id="fSubject">${state.subjects.map(s=>`<option value="${s.id}" ${t?.subjectId===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></label><label>Priority<select id="fPriority">${['low','medium','high'].map(p=>`<option ${t?.priority===p?'selected':''}>${p}</option>`).join('')}</select></label><label>Due date<input id="fTaskDue" type="date" value="${t?.due||today()}"></label><label>Time<input id="fTime" type="time" value="${t?.time||''}"></label></div><div class="modal-actions"><button class="btn ghost">Cancel</button><button type="button" class="btn primary" onclick="saveTask('${id||''}')">${t?'Save changes':'Create task'}</button></div>`)};
window.saveTask=id=>{const title=field('fTask').value.trim();if(!title)return toast('Task title is required');const t=state.tasks.find(x=>x.id===id),data={title,subjectId:field('fSubject').value,priority:field('fPriority').value,due:field('fTaskDue').value,time:field('fTime').value};if(t)Object.assign(t,data);else state.tasks.push({id:uid(),...data,status:'pending'});save();closeModal();render();toast(t?'Task updated':'Task created')};window.deleteTask=id=>{if(!confirm('Delete this task?'))return;state.tasks=state.tasks.filter(t=>t.id!==id);save();render();toast('Task deleted')};window.toggleTask=id=>{const t=state.tasks.find(x=>x.id===id);t.status=t.status==='completed'?'pending':'completed';if(t.status==='completed'){state.activity.push({date:today(),minutes:30});beep()}save();render()};
window.newNote=()=>{const n={id:uid(),title:'Untitled note',subjectId:state.subjects[0]?.id||'',content:'',updated:today()};state.notes.unshift(n);selectedNote=n.id;save();render()};window.selectNote=id=>{selectedNote=id;render()};window.editNote=(k,v)=>{const n=state.notes.find(x=>x.id===selectedNote);n[k]=v;n.updated=today();save()};window.deleteNote=id=>{state.notes=state.notes.filter(x=>x.id!==id);selectedNote=state.notes[0]?.id;save();render()};
window.moveMonth=n=>{calDate.setMonth(calDate.getMonth()+n);render()};window.updateAppearance=(key,value)=>{state.settings[key]=value;rememberAppearance(state.settings);save();applyTheme();render()};window.setTheme=t=>updateAppearance('theme',t);window.toggleSetting=k=>{state.settings[k]=!state.settings[k];save();render()};
window.appearanceSettingsMarkup=()=>{const s={...seed.settings,...state.settings},themes=[['nestlyra','Nestlyra · Default','#4C5FD5'],['auto','Automatic','#7181EA'],['dark','Midnight','#111d2e'],['ocean','Ocean','#1b9cff'],['cyber','Cyber','#ff3e9d'],['matrix','Matrix','#3cdb71'],['light','Classic Light','#dce8f5']];return `<div class="card-title"><h3>Appearance</h3><span>Personal to this user</span></div><div class="appearance-group"><h4>Optimized theme</h4><div class="theme-list labeled">${themes.map(([name,label,color])=>`<button type="button" title="${label}" class="theme-chip ${s.theme===name?'active':''}" style="--swatch:${color}" onclick="setTheme('${name}')"><span>${label}</span></button>`).join('')}</div><p class="settings-note">Nestlyra is the default for new users. Your selected theme remains saved after future sign-ins.</p></div><div class="appearance-controls"><label>Text style<select onchange="updateAppearance('fontStyle',this.value)"><option value="modern" ${s.fontStyle==='modern'?'selected':''}>Modern — Inter + Poppins</option><option value="system" ${s.fontStyle==='system'?'selected':''}>System — Segoe UI</option><option value="editorial" ${s.fontStyle==='editorial'?'selected':''}>Editorial — Georgia</option></select></label><label>Interface text size<select onchange="updateAppearance('textScale',this.value)"><option value="compact" ${s.textScale==='compact'?'selected':''}>Compact</option><option value="normal" ${s.textScale==='normal'?'selected':''}>Comfortable</option><option value="large" ${s.textScale==='large'?'selected':''}>Large</option></select></label></div><div class="appearance-group login-image-settings"><h4>Login-page background</h4><p class="task-meta">Upload a JPG, PNG or WebP image. It is resized and optimized before saving.</p><div class="appearance-controls"><label>Image framing<select onchange="updateAppearance('loginImagePosition',this.value)"><option value="left" ${s.loginImagePosition==='left'?'selected':''}>Focus left</option><option value="center" ${s.loginImagePosition==='center'?'selected':''}>Focus center</option><option value="right" ${s.loginImagePosition==='right'?'selected':''}>Focus right</option></select></label><label>Text overlay<select onchange="updateAppearance('loginImageShade',this.value)"><option value="soft" ${s.loginImageShade==='soft'?'selected':''}>Soft</option><option value="balanced" ${s.loginImageShade==='balanced'?'selected':''}>Balanced</option><option value="strong" ${s.loginImageShade==='strong'?'selected':''}>Strong</option></select></label></div><div class="appearance-image-actions"><label class="btn primary appearance-upload">Upload image<input type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadLoginImage(event)"></label><button type="button" class="btn ghost" onclick="resetLoginImage()">Restore default background</button><small>${s.loginImage?'Custom image active':'Default Nestlyra background active'}</small></div></div>`};
window.uploadLoginImage=event=>{const input=event.target,file=input.files?.[0];if(!file)return;if(file.size>8*1024*1024){input.value='';return toast('Choose an image smaller than 8 MB')}const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const limit=1600,scale=Math.min(1,limit/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);state.settings.loginImage=canvas.toDataURL('image/jpeg',.78);rememberAppearance(state.settings);save();applyTheme();render();toast('Login background optimized and saved')};image.onerror=()=>toast('This image could not be opened');image.src=reader.result};reader.readAsDataURL(file)};
window.resetLoginImage=()=>{state.settings.loginImage='';rememberAppearance(state.settings);save();applyTheme();render();toast('Default login background restored')};
window.calendarDay=date=>{const existing=(state.events||[]).filter(e=>e.date===date),jobs=(state.jobApplications||[]).filter(a=>a.followUpDate===date&&!jobTerminal(a.status));modal(`<h2>${date}</h2>${existing.map(e=>`<div class="setting-row"><span><strong>${escapeHtml(e.title)}</strong><small>${e.time||'All day'}</small></span><span><button type="button" class="mini-btn" onclick="eventModal('${e.id}')">✎</button><button type="button" class="mini-btn" onclick="deleteEvent('${e.id}')">×</button></span></div>`).join('')}${jobs.map(a=>`<div class="setting-row"><span><strong>Job follow-up: ${escapeHtml(a.company)}</strong><small>${escapeHtml(a.jobTitle)}</small></span><button type="button" class="mini-btn" onclick="jobDetails('${a.id}')">→</button></div>`).join('')}${!existing.length&&!jobs.length?'<div class="empty">Nothing scheduled.</div>':''}<div class="modal-actions"><button class="btn ghost">Close</button><button type="button" class="btn primary" onclick="eventModal('', '${date}')">+ Add event</button></div>`)};
window.eventModal=(id='',date=today())=>{const e=(state.events||[]).find(x=>x.id===id);modal(`<h2>${e?'Edit':'Add'} calendar event</h2><div class="form-grid"><label class="full">Title<input id="fEventTitle" value="${escapeHtml(e?.title||'')}"></label><label>Date<input id="fEventDate" type="date" value="${e?.date||date}"></label><label>Time<input id="fEventTime" type="time" value="${e?.time||''}"></label><label>Repeat<select id="fEventRepeat"><option value="none">Does not repeat</option><option value="weekly" ${e?.repeat==='weekly'?'selected':''}>Weekly</option><option value="monthly" ${e?.repeat==='monthly'?'selected':''}>Monthly</option></select></label><label>Color<input id="fEventColor" type="color" value="${e?.color||'#7c5cff'}"></label></div><div class="modal-actions"><button class="btn ghost">Cancel</button><button type="button" class="btn primary" onclick="saveEvent('${id}')">Save event</button></div>`)};
window.saveEvent=id=>{const title=field('fEventTitle').value.trim();if(!title)return toast('Event title is required');state.events=state.events||[];const data={title,date:field('fEventDate').value,time:field('fEventTime').value,repeat:field('fEventRepeat').value,color:field('fEventColor').value},e=state.events.find(x=>x.id===id);if(e)Object.assign(e,data);else state.events.push({id:uid(),...data});save();closeModal();render();toast('Event saved')};
