function workspaceData(){return {subjects:structuredClone(state.subjects),tasks:structuredClone(state.tasks),events:structuredClone(state.events||[]),jobApplications:structuredClone(state.jobApplications||[]),notes:structuredClone(state.notes),activity:structuredClone(state.activity)}}
