window.switchWorkspace=id=>{if(id===state.activeWorkspace)return;storeWorkspace();const w=state.workspaces.find(x=>x.id===id);if(!w)return;state.activeWorkspace=id;const d=w.data||{subjects:[],tasks:[],events:[],jobApplications:[],notes:[],activity:[]};Object.assign(state,structuredClone(d));state.jobApplications=state.jobApplications||[];selectedSubject=state.subjects[0]?.id||'';selectedNote=state.notes[0]?.id;save();viewName='dashboard';render();toast(`Workspace: ${w.name}`)};
window.workspaceModal=id=>{const w=state.workspaces.find(x=>x.id===id);modal(`<h2>${w?'Edit':'Create'} workspace</h2><label>Workspace name<input id="fWorkspace" value="${escapeHtml(w?.name||'')}"></label><div class="modal-actions">${w&&state.workspaces.length>1?`<button type="button" class="btn danger" onclick="deleteWorkspace('${id}')">Delete</button>`:''}${w?`<button type="button" class="btn ghost" onclick="archiveWorkspace('${id}')">${w.archived?'Restore':'Archive'}</button>`:''}<button class="btn ghost">Cancel</button><button type="button" class="btn primary" onclick="saveWorkspace('${id||''}')">Save</button></div>`)};
window.saveWorkspace=id=>{const name=field('fWorkspace').value.trim();if(!name)return toast('Workspace name is required');if(id){state.workspaces.find(x=>x.id===id).name=name}else{storeWorkspace();const w={id:uid(),name,archived:false,data:{subjects:[],tasks:[],events:[],jobApplications:[],notes:[],activity:[]}};state.workspaces.push(w);state.activeWorkspace=w.id;Object.assign(state,structuredClone(w.data))}save();closeModal();viewName='dashboard';render()};
