window.profileModal=()=>modal(`<h2>User profile</h2><div class="form-grid"><label class="full">Display name<input id="fProfileName" value="${escapeHtml(state.profile?.name||'')}"></label><label class="full">New local PIN / password<input id="fProfilePin" type="password" minlength="4" placeholder="Leave blank to keep current"></label></div><p class="task-meta">When Supabase is connected, password reset and account security are handled by secure email verification.</p><div class="modal-actions"><button class="btn ghost">Cancel</button><button type="button" class="btn primary" onclick="saveProfile()">Save profile</button></div>`);
