function paintTimer(){const el=document.getElementById('timerDisplay');if(el)el.textContent=`${String(Math.floor(timerSeconds/60)).padStart(2,'0')}:${String(timerSeconds%60).padStart(2,'0')}`}window.setTimer=m=>{window.pauseTimer();timerInitial=m*60;timerSeconds=timerInitial;paintTimer();toast(`${m}-minute timer ready`)};window.startTimer=()=>{if(timerHandle)return;timerHandle=setInterval(()=>{timerSeconds--;paintTimer();if(timerSeconds<=0){clearInterval(timerHandle);timerHandle=null;state.activity.push({date:today(),minutes:Math.round(timerInitial/60)});save();beep();timerSeconds=timerInitial;render();toast('Focus session completed!')}},1000);render()};window.pauseTimer=()=>{if(timerHandle){clearInterval(timerHandle);timerHandle=null}paintTimer()};window.resetTimer=()=>{window.pauseTimer();timerSeconds=timerInitial;render()};
window.buildSubjectExport=(ids=[])=>{const chosen=new Set(ids),subjects=state.subjects.filter(subject=>chosen.has(subject.id)),slug=subjects.length===1?subjects[0].name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48):`${subjects.length}-subjects`;return{filename:`study-${slug||'subject'}-${today()}.json`,data:JSON.stringify({format:'study-tracker-subjects',version:2,subjects},null,2),subjects}}
window.exportSubjectsModal=()=>{if(!state.subjects.length)return toast('Create or import a subject first');modal(`<div class="subject-export-picker"><p class="task-meta">Select one or multiple subjects. Unselected subjects and all other workspace data stay private.</p><div class="subject-export-actions"><button type="button" class="mini-btn" onclick="toggleSubjectExportSelection(true)">Select all</button><button type="button" class="mini-btn" onclick="toggleSubjectExportSelection(false)">Clear</button></div><fieldset><legend class="sr-only">Subjects to export</legend>${state.subjects.map(subject=>{const modules=subject.modules||[],topics=modules.reduce((count,module)=>count+(module.topics||[]).length,0);return`<label class="subject-export-option"><input type="checkbox" data-export-subject value="${escapeHtml(subject.id)}" checked><span><strong>${escapeHtml(subject.name)}</strong><small>${modules.length} module${modules.length===1?'':'s'} · ${topics} topic${topics===1?'':'s'}</small></span></label>`}).join('')}</fieldset><div class="modal-actions"><button type="button" class="btn ghost" onclick="closeModal()">Cancel</button><button type="button" class="btn primary" onclick="exportSelectedSubjects()">Export selected</button></div></div>`,'Export subjects')}
