window.exportSelectedSubjects=()=>{const ids=[...document.querySelectorAll('[data-export-subject]:checked')].map(input=>input.value);if(!ids.length)return toast('Choose at least one subject');const payload=buildSubjectExport(ids);download(payload.filename,payload.data,'application/json');closeModal();toast(`${payload.subjects.length} subject${payload.subjects.length===1?'':'s'} exported`)};
window.exportJSON=window.exportSubjectsModal;function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
window.downloadSubjectTemplate=()=>download('study-subjects-template.json',JSON.stringify({format:'study-tracker-subjects',version:1,subjects:[{name:'Example Subject',description:'What you want to learn',color:'#7c5cff',icon:'EX',modules:[{name:'Module 1',topics:[{name:'Topic 1',status:'not-started',due:''}]}]}]},null,2),'application/json');
window.exportExcel=()=>{if(!window.XLSX)return toast('Excel library unavailable');const wb=XLSX.utils.book_new(),rows=allTopics().map(t=>({Subject:subjectName(t.subjectId),Module:t.module,Topic:t.name,Status:t.status,'Due Date':t.due||''}));XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Subjects');XLSX.writeFile(wb,`tracker-subjects-${today()}.xlsx`)};
function validImportedSubject(s){return s&&typeof s.name==='string'&&Array.isArray(s.modules)&&s.modules.every(m=>m&&typeof m.name==='string'&&Array.isArray(m.topics))}
function prepareImportedSubject(s){return {id:uid(),name:s.name.trim(),description:String(s.description||''),color:/^#[0-9a-f]{6}$/i.test(s.color||'')?s.color:'#7c5cff',icon:String(s.icon||s.name.slice(0,2)).slice(0,3).toUpperCase(),modules:s.modules.map(m=>({id:uid(),name:m.name.trim(),topics:m.topics.map(t=>({id:uid(),name:String(t.name||'Untitled topic'),status:['not-started','in-progress','completed'].includes(t.status)?t.status:'not-started',due:/^\d{4}-\d{2}-\d{2}$/.test(t.due||'')?t.due:''}))}))}}
importInput.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result),subjects=Array.isArray(x)?x:x.subjects;if(!Array.isArray(subjects)||!subjects.length||!subjects.every(validImportedSubject))throw Error();state.subjects.push(...subjects.map(prepareImportedSubject));selectedSubject=state.subjects[0]?.id||'';save();render();toast(`${subjects.length} subject${subjects.length===1?'':'s'} imported`)}catch{toast('Invalid subjects JSON — download the sample format')}finally{importInput.value=''}};r.readAsText(file)});
window.signOut=async()=>{familyStopVoice?.();sessionStorage.removeItem('studyTracker.family.role');sessionStorage.removeItem('studyTracker.family.sessionType');sessionStorage.removeItem('studyTracker.family.loginIntent');sessionStorage.setItem('studyTracker.forceLogin','1');if(sb&&cloudUser){await sb.auth.signOut();clearClientAccount()}location.reload()};
window.deleteAccountModal=()=>modal(`<h2>Delete account permanently</h2><p>This deletes your login, tracker data, workspaces, group memberships, messages and activity. Owned groups transfer to another member when possible; otherwise they are deleted. You must create a new account to use this email again.</p><label>Type <strong>DELETE</strong> to confirm<input id="deleteConfirm" autocomplete="off" placeholder="DELETE"></label><div class="modal-actions"><button class="btn ghost">Cancel</button><button type="button" class="btn danger" onclick="deleteAccount()">Delete account permanently</button></div>`);
window.deleteAccount=async()=>{if(field('deleteConfirm').value!=='DELETE')return toast('Type DELETE to confirm');const button=document.querySelector('.modal-actions .danger');if(button){button.disabled=true;button.textContent='Deleting…'}if(sb&&cloudUser){const {data,error}=await sb.rpc('delete_own_account');if(error||data!==true){if(button){button.disabled=false;button.textContent='Delete account permanently'}return toast(error?.message||'Account deletion failed')}try{await sb.auth.signOut({scope:'local'})}catch{}}if(typeof familyDeleteLocalLearnerData==='function')familyDeleteLocalLearnerData();clearClientAccount();redirectWithNotice('Account permanently deleted. Create a new account to continue.')};
const trackerModal=document.querySelector('#modal');modalClose.onclick=closeModal;trackerModal.addEventListener('click',e=>{if(e.target===trackerModal)closeModal()});trackerModal.addEventListener('cancel',e=>{e.preventDefault();closeModal()});
nav.addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b)setView(b.dataset.view)});menuBtn.onclick=()=>setNavigationOpen(!document.querySelector('.sidebar')?.classList.contains('open'));document.querySelector('#sidebarScrim')?.addEventListener('click',()=>setNavigationOpen(false));document.addEventListener('keydown',event=>{if(event.key==='Escape')setNavigationOpen(false)});addEventListener('resize',()=>{if(innerWidth>760)setNavigationOpen(false)});addEventListener('popstate',event=>{if(app.classList.contains('hidden'))return;const previous=event.state?.nestlyraView||'dashboard';setView(previous,{fromHistory:true})});quickAdd.onclick=()=>taskModal();loginForm.addEventListener('submit',login);createLearnerAccountBtn.onclick=createLearnerAccount;document.querySelectorAll('[data-login-faq]').forEach(button=>button.onclick=loginFaqModal);googleLoginBtn.onclick=()=>{if(!sb)return toast('Cloud login is unavailable');sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin}})};avatar.onclick=()=>setView('settings');analogClock.onclick=()=>setView('calendar');sideTimer.onclick=()=>setView('timer');globalSearch.addEventListener('input',e=>{const q=e.target.value.toLowerCase();if(q.length<2)return;const s=state.subjects.find(x=>x.name.toLowerCase().includes(q));if(s){selectedSubject=s.id;return setView('subject')}const j=(state.jobApplications||[]).find(x=>`${x.company} ${x.jobTitle}`.toLowerCase().includes(q));if(j){jobQuery=q;setView('jobs')}});notifBtn.onclick=()=>{const overdue=state.tasks.filter(t=>t.due<today()&&t.status!=='completed').length,jobs=(state.jobApplications||[]).filter(jobDue).length;toast(overdue||jobs?`${overdue} overdue study task${overdue===1?'':'s'} · ${jobs} job follow-up${jobs===1?'':'s'} due`:'You are all caught up')};
function tickClock(){const d=new Date(),h=(d.getHours()%12)*30+d.getMinutes()/2,m=d.getMinutes()*6,s=d.getSeconds()*6;analogClock.querySelector('.hour').style.transform=`rotate(${h}deg)`;analogClock.querySelector('.minute').style.transform=`rotate(${m}deg)`;analogClock.querySelector('.second').style.transform=`rotate(${s}deg)`}tickClock();setInterval(tickClock,1000);
async function boot(){
 try{
  applyTheme();cleanAppUrl();
  const notice=sessionStorage.getItem(NOTICE_KEY);if(notice){sessionStorage.removeItem(NOTICE_KEY);setTimeout(()=>toast(notice),180)}
  const hadCloudAccount=Boolean(localStorage.getItem(CLOUD_ACCOUNT_KEY)||state.profile?.email||(state.profile&&!state.profile.pin));
  if(sessionStorage.getItem('studyTracker.forceLogin')){sessionStorage.removeItem('studyTracker.forceLogin');return}
  if(sb){
   const {data}=await sb.auth.getSession();
   if(data.session){
    const verified=await sb.auth.getUser();
    if(verified.error||!verified.data?.user){await invalidateCloudSession();return}
    cloudUser=verified.data.user;markCloudAccount();
    try{
     if(typeof familyResolveAuthenticatedRole==='function')await familyResolveAuthenticatedRole(cloudUser);
     await loadCloud();showApp();
    }catch(e){await sb.auth.signOut({scope:'local'});clearClientAccount();toast(e.message||'Cloud account could not be loaded')}
   }else if(hadCloudAccount){clearClientAccount();setTimeout(()=>toast('Your cloud session is no longer valid. Sign in or create a new account.'),150)}
   else if(state.profile)showApp()
  }else if(state.profile)showApp()
 }finally{document.documentElement.classList.remove('session-pending')}
}
boot();if('serviceWorker'in navigator){const hadController=Boolean(navigator.serviceWorker.controller);let refreshing=false;navigator.serviceWorker.addEventListener?.('controllerchange',()=>{if(!hadController||refreshing)return;refreshing=true;location.reload()});navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{})}

googleLoginBtn.onclick=async()=>{if(!sb)return toast('Cloud login is unavailable');if(typeof familyPrepareLearnerLogin==='function')familyPrepareLearnerLogin();const {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+location.pathname}});if(error)toast(error.message)};

async function validateCloudAccount(){if(!sb||!cloudUser||invalidatingSession)return;const {data,error}=await sb.auth.getUser();if(error||!data?.user||data.user.id!==cloudUser.id)invalidateCloudSession('This account was deleted. Create a new account to continue.')}
setInterval(validateCloudAccount,30000);
addEventListener('focus',validateCloudAccount);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')validateCloudAccount()});
